// Title: Crop a worksheet PNG to a defined rectangle using System.Drawing after rendering with Aspose.Cells in C#
// Common Searches: C# code to crop a specific area from a worksheet image generated by Aspose.Cells | using System.Drawing to extract a rectangle from a PNG rendered from an Excel sheet | Aspose.Cells SheetRender crop PNG to custom dimensions in .NET | how to trim a rendered Excel worksheet PNG to a region in C# | programmatically cut out part of a worksheet PNG with System.Drawing and Aspose.Cells
// Tags: System.Drawing bitmap cropping | Aspose.Cells SheetRender PNG output | C# extract rectangle from worksheet image | crop PNG region after Excel rendering | image processing Aspose.Cells output

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// The example loads an Excel workbook, renders the first worksheet to a PNG file using Aspose.Cells SheetRender, and demonstrates how to open the resulting PNG with System.Drawing to crop it to a specified rectangle, including basic file checks and exception handling.
class Program
{
    static void Main()
    {
        try
        {
            // Define input and output file paths
            string inputPath = "input.xlsx";
            string outputPath = "output.png";

            // Verify that the input workbook exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Error: Input file '{inputPath}' not found.");
                return;
            }

            // Load the workbook
            Workbook workbook = new Workbook(inputPath);

            // Get the first worksheet (or specify another index/name as needed)
            Worksheet sheet = workbook.Worksheets[0];

            // Configure rendering options (default format is PNG)
            ImageOrPrintOptions imgOptions = new ImageOrPrintOptions
            {
                // Optional: set resolution, page size, etc.
                // HorizontalResolution = 300,
                // VerticalResolution = 300
            };

            // Render the worksheet to an image file
            SheetRender sheetRender = new SheetRender(sheet, imgOptions);
            sheetRender.ToImage(0, outputPath);

            Console.WriteLine($"Worksheet successfully rendered to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            // Log any unexpected errors
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
